// Shiganshina: entry point for shiganshina.html. Fan work after Hajime Isayama's Attack on Titan: Wall Maria's southern
// district, generated by tools/make-shiganshina.py, on the shared engine; its walls and gates in landmarks.js, the Titans
// and the Garrison in life.js, the Colossal Titan and the Survey Corps in events.js.
import {report,LOAD,configureLoading,installErrorHandlers} from '../core/diag.js';
import {boot} from '../core/shell.js';
import {build} from '../engine/build.js';
import {landmarks} from './landmarks.js';
import {life} from './life.js';
import {events} from './events.js';
import {oldtown} from '../edinburgh/oldtown.js';
import {crowds} from '../core/crowds.js';
import {navmap} from '../core/navmap.js';
installErrorHandlers();window.LOAD=LOAD;
configureLoading({
  lines:[
    'Humanity lives inside three walls, each fifty metres high: Maria, Rose and Sina.',
    'Where a road leaves a wall there is a district, walled in its own half-circle, so the Titans come there first.',
    'Shiganshina is Wall Maria\'s southern district. A canal runs through it, in by the outer wall and out by the inner.',
    'The Garrison mans the walls. The Survey Corps rides out beyond them, and fewer come back.',
  ],
  prefix:'raising Shiganshina… ',labels:{'map-data':'surveying the district',ground:'laying the fields',buildings:'building the town',details:'manning the walls',landmarks:'raising Wall Maria',el:'',ui:'opening the gates'}});
const ctx=window._iz={defaultCity:'shiganshina',models:[landmarks],extras:[{name:'life',fn:life},{name:'oldtown',fn:oldtown},{name:'crowds',fn:crowds},{name:'navmap',fn:navmap},{name:'events',fn:events}]};
ctx.extras=ctx.extras.map(e=>({name:e.name,fn:api=>{const t0=performance.now();try{return e.fn(api);}finally{api.ctx.details=api.ctx.details||{};(api.ctx.details.extraMs=api.ctx.details.extraMs||{})[e.name]=Math.round(performance.now()-t0);}}}));
boot(()=>build(ctx));
